package com.example.mobileapp.data.local.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

@Entity(
    tableName = "properties",
    indices = [Index(value = ["serverId"], unique = true), Index(value = ["propertyCode"]), Index(value = ["status"])]
)
data class PropertyEntity(
    @PrimaryKey(autoGenerate = true) val localId: Long = 0,
    val serverId: Long? = null,
    // Generated by the server; the app must not invent property codes.
    val propertyCode: String? = null,
    val title: String,
    val propertyType: String,
    val listingType: String, // sale, rent, lease
    val province: String,
    val district: String = "",
    val address: String = "",
    val price: Long,
    val currency: String = "AFN",
    val status: String = "available",
    val description: String = "",
    val bedrooms: Int? = null,
    val bathrooms: Int? = null,
    val areaSquareMeters: Double? = null,
    val photoUrlsJson: String = "[]",
    val updatedAtEpochMillis: Long = System.currentTimeMillis(),
    val syncState: String = "pending" // pending, synced, conflict, failed
)
